/** user-defined types **/

export type CommandError = { message: string }
/**
 * Live connection state for a host (tech-gui.md §4.1). Internally tagged so the
 * frontend consumes a discriminated union keyed on `kind`.
 */
export type ConnectionStatusDto = { kind: "unknown" } | { kind: "connecting" } | { kind: "connected" } | { kind: "failed"; message: string }
/**
 * A background error surfaced to the user.
 */
export type Error = { message: string }
/**
 * A full-file editor read failed for a specific SFTP tab.
 */
export type FileContentReadFailed = { sessionId: number; path: string; error: string }
/**
 * Full UTF-8 remote file content for the in-app editor.
 */
export type FileContentReady = { sessionId: number; path: string; content: string }
/**
 * A file or directory in an SFTP panel listing (tech-gui.md §4.1). Maps from the
 * core `FileEntry`; `path` is the absolute path the frontend marks entries by.
 */
export type FileEntryDto = { name: string; path: string; size: number; isDir: boolean }
/**
 * Preview bytes for a remote file (tech-gui.md §4.3). Stamped with `sessionId`; the
 * core `FilePreviewReady` carries only the path + content (§3.4).
 */
export type FilePreview = { sessionId: number; path: string; content: string }
/**
 * Result of an in-app editor save.
 */
export type FileWriteDone = { sessionId: number; path: string; ok: boolean; error?: string | null }
/**
 * General application preferences shared by both TUI and GUI.
 */
export type GeneralConfigDto = { refreshInterval: number; defaultShell: string; sshCommand: string; maxConcurrentConnections: number; externalEditor: string; largeFileMb: number; promptLargeFiles: boolean; autoUploadExternal: boolean }
/**
 * A host as the frontend sees it — password and private-key material omitted
 * (tech-gui.md §3.4). `hasKey` reports whether an identity file is configured;
 * the key path itself never crosses the boundary.
 */
export type HostDto = { name: string; hostname: string; user: string; port: number; tags: string[]; notes?: string | null; source: HostSourceDto; hasKey: boolean; passwordAuthDisabled?: boolean | null; monitoring: MonitorModeDto; monitorPort?: number | null; localForwards: LocalForwardDto[]; tunnelAutostart: boolean; forwardAgent: boolean }
/**
 * Inbound host form payload for `save_host` (tech-gui.md §4.1, Stage 4.1). Always
 * builds a **manual** `Host`: editing an SSH-config import saves a copy that shadows
 * it, and `~/.ssh/config` itself is never written.
 * `password`/`identityFile` arrive here (the create/edit form owns them) but never
 * travel back out: the outbound `HostDto` omits both (§3.4). Inbound only, so it
 * derives `Deserialize` (not `Serialize`).
 */
export type HostInputDto = { name: string; hostname: string; user: string; port: number; identityFile?: string | null; password?: string | null; proxyJump?: string | null; tags: string[]; notes?: string | null; monitoring?: MonitorModeDto | null; monitorPort?: number | null; localForwards: LocalForwardDto[]; tunnelAutostart: boolean; forwardAgent: boolean }
/**
 * Host origin, mirrors `omnyssh_core::ssh::client::HostSource`.
 */
export type HostSourceDto = "sshConfig" | "manual"
/**
 * A host's connection status changed (tech-gui.md §4.3).
 */
export type HostStatusChanged = { hostName: string; status: ConnectionStatusDto }
/**
 * Full host list broadcast. Emitted by `reload_hosts` after refreshing the
 * cache; the bridge does not map `HostsLoaded` (tech-gui.md §3.4).
 */
export type HostsLoaded = HostDto[]
/**
 * A private key is encrypted and no passphrase is cached yet. Frontends prompt
 * once per key path; the passphrase never crosses back out of the backend.
 */
export type KeyPassphraseRequired = { hostName: string; keyPath: string }
/**
 * Key setup finished successfully — key auth is configured (tech-gui.md §4.3).
 * `keyPath` is the generated private-key path (a path, never key material, §3.4).
 */
export type KeySetupComplete = { hostName: string; keyPath: string }
/**
 * Key setup failed before touching the server's auth config (tech-gui.md §4.3).
 * Password authentication is never disabled unless a key was verified first.
 */
export type KeySetupFailed = { hostName: string; error: string }
/**
 * A progress step of an auto key-setup run (tech-gui.md §4.3). Mapped by the shared
 * engine bridge from `CoreEvent::KeySetupProgress`; the host name identifies the run.
 */
export type KeySetupProgress = { hostName: string; step: KeySetupStepDto }
/**
 * Key setup rolled the server's sshd config back after a late failure (tech-gui.md
 * §4.3). `result` is the human-readable rollback outcome.
 */
export type KeySetupRollback = { hostName: string; result: string }
/**
 * One step of the auto key-setup flow, for the progress view (tech-gui.md §4.2/§4.3).
 * `index` is 1-based (`1..=total`); `description` is the core's human-readable label.
 * Maps from the core `KeySetupStep`.
 */
export type KeySetupStepDto = { index: number; total: number; description: string }
/**
 * One `ssh -L` rule (tech-gui.md §4.1): listen on `bindAddress:bindPort` here and
 * reach `remoteHost:remotePort` as the host resolves it. No `bindAddress` means the
 * loopback, as with ssh.
 */
export type LocalForwardDto = { bindAddress?: string | null; bindPort: number; remoteHost: string; remotePort: number }
/**
 * A metrics snapshot for a host (tech-gui.md §4.1). The core's `Instant` is
 * flattened to `ageSeconds` (seconds since the sample) so it can serialise.
 */
export type MetricsDto = { cpuPercent?: number | null; ramPercent?: number | null; diskPercent?: number | null; uptime?: string | null; loadAvg?: string | null; osInfo?: string | null; topProcesses: ProcessDto[]; ageSeconds: number }
/**
 * A fresh metrics sample for a host (tech-gui.md §4.3).
 */
export type MetricsUpdated = { hostName: string; metrics: MetricsDto }
/**
 * How a host is watched, mirrors `omnyssh_core::ssh::client::MonitorMode`
 * (tech-gui.md §4.1). `tcpPort` means reachability only — no login, no metrics.
 */
export type MonitorModeDto = "ssh" | "tcpPort"
/**
 * A connection waits for the login password of `login` (`user@host`). Answered
 * with `answer_password`; the password only ever crosses inbound. `retry` says
 * the previous one was refused; `newHostKey` is the fingerprint of a host key
 * first seen on this connection, to check before typing.
 */
export type PasswordRequired = { requestId: number; hostName: string; login: string; retry: boolean; newHostKey: string | null }
/**
 * A single process in the "top processes" panel (tech-gui.md §4.1).
 */
export type ProcessDto = { name: string; cpuPercent: number; memPercent: number }
/**
 * A service detected on a host with its quick-scan metrics (tech-gui.md §4.1).
 */
export type ServiceDto = { kind: ServiceKindDto; metrics: ServiceMetricDto[] }
/**
 * A service kind detected on a host, mirrors `omnyssh_core::event::ServiceKind`.
 * Wire names are lowercase (`docker`, `nginx`, `postgresql`, `redis`, `nodejs`);
 * if the core adds a kind, extend this enum so it is never silently dropped
 * (tech-gui.md §4.1).
 */
export type ServiceKindDto = "docker" | "nginx" | "postgresql" | "redis" | "nodejs"
/**
 * One quick-scan metric for a detected service (tech-gui.md §4.1). `MetricValue`
 * is integer-only today; widen this if the core adds a non-integral variant.
 */
export type ServiceMetricDto = { name: string; value: number }
/**
 * Services detected on a host by the discovery quick-scan (tech-gui.md §4.3).
 */
export type ServicesDetected = { hostName: string; services: ServiceDto[] }
/**
 * Discovery failed for a host (tech-gui.md §4.3).
 */
export type ServicesFailed = { hostName: string; message: string }
/**
 * An SFTP session connected (tech-gui.md §4.3). The per-session forwarder stamps
 * `sessionId` from the channel's owner — the core `SftpConnected` carries only the
 * host name (§3.4).
 */
export type SftpConnected = { sessionId: number; hostName: string }
/**
 * A remote directory listing completed for one SFTP tab (tech-gui.md §4.3). Stamped
 * with `sessionId`; the core `FileDirListed` carries only the path (§3.4).
 */
export type SftpDirListed = { sessionId: number; path: string; entries: FileEntryDto[] }
/**
 * An SFTP operation reported a failure (tech-gui.md §4.3). The core emits this on a
 * listing error with a human reason; it does not by itself tear the session down.
 */
export type SftpDisconnected = { sessionId: number; reason: string }
/**
 * A mutating SFTP op (upload/download/mkdir/rename/delete) finished (tech-gui.md
 * §4.3). The core's `Result<(), String>` is flattened to `ok` + an optional `error`.
 */
export type SftpOpDone = { sessionId: number; ok: boolean; error?: string | null }
/**
 * A saved command snippet as the frontend sees it (tech-gui.md §4.1). Crosses the
 * boundary both ways — outbound for `list_snippets`, inbound for `save_snippet` —
 * so it derives `Deserialize` too. Optional fields are omitted when absent, matching
 * the sparse `snippets.toml` the TUI writes.
 */
export type SnippetDto = { name: string; command: string; scope: SnippetScopeDto; host?: string | null; tags?: string[] | null; params?: string[] | null }
/**
 * Result of running a snippet on one host (tech-gui.md §4.3). Emitted directly by
 * `execute_snippet` per host (one-shot `SshSession::run_command`), not via the
 * shared bridge — the same "the command owns the result" pattern the SFTP
 * per-session forwarder uses (§3.4). The core's `Result<String, String>` is
 * flattened to `ok` + `output` (stdout on success, the error message on failure).
 */
export type SnippetResult = { hostName: string; snippetName: string; ok: boolean; output: string }
/**
 * Snippet scope, mirrors `omnyssh_core::config::snippets::SnippetScope`. Wire
 * names are lowercase (`global`, `host`).
 */
export type SnippetScopeDto = "global" | "host"
/**
 * Raw PTY output bytes for a terminal session's per-session `Channel` (tech-gui.md
 * §3.3/§3.6). Deliberately **not** `Serialize`: that dodges the blanket
 * `Serialize -> IpcResponse` mapping (which would JSON-encode to a slow `number[]`),
 * so the bytes ride the channel as a raw `ArrayBuffer` that xterm writes directly.
 * Only ever sent, never received — the sole non-DTO on the boundary.
 */
export type TerminalBytes = number[]
/**
 * A terminal session's remote shell exited or its connection dropped (tech-gui.md
 * §4.3). Carries the **public** registry id (the bridge maps the core's inner PTY
 * id, §3.4); the frontend tears the tab down. User-initiated closes never emit this.
 */
export type TerminalExited = { sessionId: number }
/**
 * Live transfer progress (tech-gui.md §4.3). The payload is `TransferProgressDto`,
 * routed to its owning session via `transfer_owner` (§3.4/§4.1).
 */
export type TransferProgress = TransferProgressDto
/**
 * Live progress for one SFTP upload/download (tech-gui.md §4.1). The GUI allocates
 * `transferId` when it issues the transfer and resolves its owning `sessionId` via
 * `transfer_owner` (§3.4); `done`/`total` are byte counts (`total` is `0` when the
 * remote size could not be determined).
 */
export type TransferProgressDto = { sessionId: number; transferId: number; rootName: string; currentFile: string; stage: string; bytesDone: number; bytesTotal: number; filesDone: number; filesTotal: number }
/**
 * What this desktop allows the tray (tech-gui.md §4.2 `set_tray_behavior`): an icon
 * at all, and hiding a minimized window into it.
 */
export type TraySupportDto = { available: boolean; minimize: boolean }
/**
 * A host's port-forwarding tunnel changed state (tech-gui.md §4.3).
 */
export type TunnelStatusChanged = { hostName: string; status: TunnelStatusDto }
/**
 * Where a host's tunnel stands (tech-gui.md §4.1). Internally tagged on `kind`,
 * like `ConnectionStatusDto`.
 */
export type TunnelStatusDto = { kind: "connecting" } | { kind: "up" } | { kind: "retrying"; message: string } | { kind: "failed"; message: string } | { kind: "stopped" }
/**
 * A newer release was found by the startup check (tech-gui.md §4.3). Mapped by the
 * shared engine bridge from `CoreEvent::UpdateAvailable`; drives the update banner.
 */
export type UpdateAvailable = { info: UpdateInfoDto }
/**
 * Update-checker preferences, mirrors core `UpdateConfig` (tech-gui.md §4.3). Crosses
 * both ways: outbound for the settings screen, inbound for `save_update_config`.
 */
export type UpdateConfigDto = { checkOnStartup: boolean; skipVersion: string }
/**
 * A newer release the app can offer (tech-gui.md §4.1). `version` is the latest
 * version (no leading `v`); `url` is the release page; `canSelfUpdate` mirrors the
 * core's self-update eligibility. The core `UpdateInfo` has no release-notes field, so
 * none is invented (§4.1).
 */
export type UpdateInfoDto = { version: string; url: string; tag: string; canSelfUpdate: boolean }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
